```

```c
// stub.c (minimal sketch)
typedef void (*LogCallback)(void*, const char*, size_t);
static LogCallback global_cb = NULL;
static void* global_ctx = NULL;

void register_log_callback(LogCallback cb, void* ctx) {
    global_cb = cb;
    global_ctx = ctx;
}

void start_streaming() {
    // Simulate async log generation
    for (int i = 0; i < 5; i++) {
        if (global_cb) {
            const char* line = "Sample log line\n";
            global_cb(global_ctx, line, strlen(line));
        }
        usleep(100000); // 100ms delay
    }
}

void stop_streaming() {
    global_cb = NULL;
    global_ctx = NULL;
}
```

```go
// main.go
package main

/*
#cgo CFLAGS: -g -O2
#cgo LDFLAGS: -lpthread

#include "header.h"
#include <stdlib.h>
#include <string.h>

typedef struct {
    void* go_ctx;
    int cancelled;
} bridge_t;

static bridge_t* create_bridge(void* go_ctx) {
    bridge_t* b = malloc(sizeof(bridge_t));
    b->go_ctx = go_ctx;
    b->cancelled = 0;
    return b;
}

static void destroy_bridge(bridge_t* b) {
    free(b);
}

// Exported Go callback
extern void goLogCallback(void* go_ctx, const char* line, size_t len);

static void log_cb(void* ctx, const char* line, size_t len) {
    bridge_t* b = (bridge_t*)ctx;
    if (!b || b->cancelled) return;

    // Copy string to ensure safety
    char* copy = malloc(len + 1);
    memcpy(copy, line, len);
    copy[len] = '\0';

    goLogCallback(b->go_ctx, copy, len);
    free(copy);
}
*/
import "C"
import (
    "context"
    "fmt"
    "runtime"
    "sync"
    "time"
    "unsafe"
)

type logStream struct {
    ch    chan string
    ctx   context.Context
    cancel context.CancelFunc
    bridge *C.bridge_t
}

var (
    streams sync.Map // map[unsafe.Pointer]*logStream
)

//export goLogCallback
func goLogCallback(goCtx unsafe.Pointer, line *C.char, len C.size_t) {
    if stream, ok := streams.Load(goCtx); ok {
        ls := stream.(*logStream)
        select {
        case ls.ch <- C.GoStringN(line, C.int(len)):
        case <-ls.ctx.Done():
            // Channel blocked or context cancelled
        default:
            // Backpressure: drop if channel full
        }
    }
}

func StreamLogs(ctx context.Context) (<-chan string, error) {
    ctx, cancel := context.WithCancel(ctx)
    ch := make(chan string, 100) // Buffer for backpressure

    // Create bridge
    bridge := C.create_bridge(unsafe.Pointer(&ch))

    ls := &logStream{
        ch:     ch,
        ctx:    ctx,
        cancel: cancel,
        bridge: bridge,
    }

    streams.Store(unsafe.Pointer(&ch), ls)

    // Register callback and start streaming
    C.register_log_callback(C.LogCallback(C.log_cb), unsafe.Pointer(bridge))

    // Start cleanup goroutine
    go func() {
        <-ctx.Done()
        cleanup(ls)
    }()

    // Start streaming in background
    go C.start_streaming()

    return ch, nil
}

func cleanup(ls *logStream) {
    // Mark as cancelled
    ls.bridge.cancelled = 1

    // Stop streaming
    C.stop_streaming()

    // Close channel
    close(ls.ch)

    // Cleanup bridge
    C.destroy_bridge(ls.bridge)

    // Remove from registry
    streams.Delete(unsafe.Pointer(&ls.ch))
}

func main() {
    ctx := context.Background()

    // Demonstrate two concurrent streams
    var wg sync.WaitGroup

    for i := 0; i < 2; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()

            streamCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
            defer cancel()

            ch, err := StreamLogs(streamCtx)
            if err != nil {
                fmt.Printf("Stream %d error: %v\n", id, err)
                return
            }

            fmt.Printf("Stream %d starting:\n", id)
            for line := range ch {
                fmt.Printf("Stream %d: %s", id, line)
            }
            fmt.Printf("Stream %d ended\n", id)
        }(i)
    }

    wg.Wait()
    fmt.Println("All streams completed")
}
```

## Why This Is Asked
This question tests end-to-end integration across C and Go in a streaming context, focusing on memory ownership, cross-language callbacks, and safe concurrent use.

## Key Concepts
- **CGO callback bridging**: Safely passing Go functions to C and handling the transition between language runtimes
- **Memory ownership**: Allocating with malloc in C, copying to Go slices, and explicitly freeing C buffers to prevent leaks
- **Streaming/partitioning**: Breaking input into blocks in C and delivering chunks incrementally to Go
- **Concurrency patterns**: Worker pools for processing multiple streams in parallel and proper error propagation through channels

## Code Example

**stream_encrypt.h**
```c
#ifndef STREAM_ENCRYPT_H
#define STREAM_ENCRYPT_H

#include <stddef.h>
#include <stdint.h>

typedef void (*chunk_cb)(const uint8_t* out, size_t out_len, int status, void* ctx);

int stream_encrypt(const uint8_t* in, size_t in_len, chunk_cb cb, void* ctx);

#endif
```

**stream_encrypt.c**
```c
#include "stream_encrypt.h"
#include <stdlib.h>
#include <string.h>

#define BLOCK_SIZE 4096

static void encrypt_block(const uint8_t* in, size_t len, uint8_t** out, size_t* out_len) {
    *out = (uint8_t*)malloc(len);
    memcpy(*out, in, len);
    *out_len = len;
}

int stream_encrypt(const uint8_t* in, size_t in_len, chunk_cb cb, void* ctx) {
    size_t offset = 0;
    while (offset < in_len) {
        size_t block_len = (offset + BLOCK_SIZE > in_len) ? (in_len - offset) : BLOCK_SIZE;
        uint8_t* encrypted = NULL;
        size_t encrypted_len = 0;

        encrypt_block(in + offset, block_len, &encrypted, &encrypted_len);
        cb(encrypted, encrypted_len, 0, ctx);
        free(encrypted);

        offset += block_len;
    }
    return 0;
}
```

**stream_encrypt.go**
```go
package main

/*
#include "stream_encrypt.h"
#include <stdlib.h>

static int call_stream_encrypt(const uint8_t* in, size_t in_len, void* ctx) {
    return stream_encrypt(in, in_len, NULL, ctx);
}
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

type StreamResult struct {
    Data []byte
    Err  error
}

var workerPool = make(chan struct{}, 4)

//export chunkCallback
func chunkCallback(out *C.uint8_t, outLen C.size_t, status C.int, ctx unsafe.Pointer) {
    result := (*chan StreamResult)(ctx)
    data := C.GoBytes(unsafe.Pointer(out), C.int(outLen))
    if status != 0 {
        *result <- StreamResult{Err: fmt.Errorf("encryption error: %d", status)}
    } else {
        *result <- StreamResult{Data: data}
    }
}

func StartEncryptStream(input string, key []byte) (<-chan []byte, <-chan error) {
    chunks := make(chan []byte, 10)
    errs := make(chan error, 10)
    resultChan := make(chan StreamResult)

    go func() {
        defer close(chunks)
        defer close(errs)

        workerPool <- struct{}{}
        defer func() { <-workerPool }()

        cInput := C.CString(input)
        defer C.free(unsafe.Pointer(cInput))

        C.stream_encrypt(
            (*C.uint8_t)(unsafe.Pointer(cInput)),
            C.size_t(len(input)),
            (C.chunk_cb)(C.chunkCallback),
            unsafe.Pointer(&resultChan),
        )

        close(resultChan)
    }()

    go func() {
        for result := range resultChan {
            if result.Err != nil {
                errs <- result.Err
            } else {
                chunks <- result.Data
            }
        }
    }()

    return chunks, errs
}

func main() {
    var wg sync.WaitGroup

    for i := 0; i < 2; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            chunks, errs := StartEncryptStream(fmt.Sprintf("message-%d", id), []byte("key"))
            for {
                select {
                case chunk, ok := <-chunks:
                    if !ok {
                        return
                    }
                    fmt.Printf("Stream %d: got chunk len=%d\n", id, len(chunk))
                case err, ok := <-errs:
                    if !ok {
                        return
                    }
                    fmt.Printf("Stream %d: error: %v\n", id, err)
                }
            }
        }(i)
    }

    wg.Wait()
}
```

